theorem covariance_posSemidef
    {Ω : Type*} [MeasurableSpace Ω] {p n : ℕ}
    {μ : Measure Ω} [IsProbabilityMeasure μ]
    {ξ : Fin n → Ω → Vector p} {δ : ℝ}
    (h : BoundedIndependentHypotheses μ ξ δ) :
    (covariance μ (sumVector ξ)).PosSemidef

theorem gaussianComparison_factor_exists {p : ℕ}
    {Q : Matrix (Fin p) (Fin p) ℝ} (hQ : Q.PosSemidef) :
    ∃ A : Matrix (Fin p) (Fin p) ℝ, A * A.transpose = Q

theorem gaussianLaw_integral_coordinate {p : ℕ}
    (A : Matrix (Fin p) (Fin p) ℝ) (j : Fin p) :
    (∫ x : Vector p, x j ∂gaussianLaw A) = 0

theorem gaussianLaw_integral_coordinate_product {p : ℕ}
    (A : Matrix (Fin p) (Fin p) ℝ) (j k : Fin p) :
    (∫ x : Vector p, x j * x k ∂gaussianLaw A) = (A * A.transpose) j k
